 if(hidden){if(menuDrawFrame!==null)cancelAnimationFrame(menuDrawFrame);menuDrawFrame=null;menuSceneCache.clear();menuCanvas.width=menuCanvas.height=0;menuCacheDirty=true;pruneMenuImages();}
