  await Promise.all([...paths].map(async src=>{menuImage(src);const localized=mainMenuLayout.objects.find(o=>o.src===src)?.localizedSources?.[PinballI18n.locale]||src;await PinballRuntimeImages.decode(menuImages.get(localized));}));
